import argparse, copy, json
from pathlib import Path

p=argparse.ArgumentParser()
p.add_argument('--execution',required=True)
p.add_argument('--source',required=True)
p.add_argument('--output',required=True)
p.add_argument('--amendments',required=True)
p.add_argument('--root-review',required=True)
a=p.parse_args()
base=Path('/tmp/flarc-feature-expansion')
execution=json.loads(Path(a.execution).read_text())
source=json.loads((Path(a.source)/'source-manifest.json').read_text())['filesSha256']
old=json.loads(Path('docs/security/matrix-evidence/current-evidence-17.json').read_text())
review=json.loads((base/'baseline-claim-review30.json').read_text())
candidates=json.loads((base/'feature44-current-evidence-candidates30.json').read_text())
reviews={r['baselineIndex']:r for r in review['claims']}
amendments=json.loads(Path(a.amendments).read_text())
root_review=json.loads(Path(a.root_review).read_text())
reviewed_hashes={r['testFile']:r['testFileSha256'] for r in amendments['evidence']}
reviewed_hashes.update({r['file']:r['sha256'] for r in root_review['sourceAmendments']})
for f,h in reviewed_hashes.items(): assert source[f]==h, ('Review source drift',f)
for r in amendments['scenarios']: assert not r['remainingActualGaps'], ('Unresolved scoped proof',r['id'],r['remainingActualGaps'])
axis_dispositions={r['id']:r['notApplicable'] for r in amendments['scenarios']}
tests={(f['name'],t['fullName']):t for f in execution['testResults'] for t in f['assertionResults']}
new_ids={r['id'] for r in candidates['candidates']}
claims=[]
unmatched=[]
def current_claim(row, provenance):
    row=copy.deepcopy(row)
    key=(row['testFile'],row['testTitle'])
    hit=tests.get(key)
    if not hit:
        unmatched.append({'id':row['id'],'testFile':key[0],'testTitle':key[1], 'provenance':provenance})
        return
    assert hit['status'] in ['passed','failed'], key
    row.update(kind='test',executionId=execution['id'],bundleSha256=execution['bundleSha256'],
               outcome='PASS' if hit['status']=='passed' else 'FAIL',
               currentTestSha256=source[key[0]],reviewProvenance=provenance)
    row.pop('source17TestSha256',None)
    for axis,disposition in axis_dispositions.get(row['id'],{}).items():
        row['dimensionDisposition'][axis]=copy.deepcopy(disposition)
    row['testFileSha256']=source[key[0]]
    for route in row.get('routeBehavior',[]):
        if 'outcome' not in route:
            assert route['status'] in [101,400,401], route
            positive=route['status']==101
            assert route['route']=='/api/v1/events'
            route.update(outcome='positive' if positive else 'negative',responseKind='feature-response' if positive else 'secure-denial',alias='/api/v1/events',observationBasis=route.get('condition','Reviewed explicit HTTP status'))
    row['rationale']='Reviewed source assertions matched to this exact file/title in the recorded execution; scope and omissions remain explicit.'
    claims.append(row)
for i,r in enumerate(old['evidence']):
    if r.get('kind')=='disposition':
        if r['id'] not in new_ids: claims.append(copy.deepcopy(r))
        continue
    if r.get('executionId')!='source17-unfiltered': continue
    row=copy.deepcopy(r)
    if i in reviews:
        reviewed=reviews[i]
        assert reviewed['reviewStatus']=='reviewed', i
        if reviewed['action']=='reject':
            unmatched.append({'id':r['id'],'baselineIndex':i,'reason':reviewed['reason']})
            continue
        row['testTitle']=reviewed['actualCurrentTestTitle']
        for key in ['scenarioScope','assertionDetails','transports','assertions','routeBehavior','commandBehavior','dimensionDisposition']:
            if key in reviewed: row[key]=reviewed[key]
        provenance={'baselineIndex':i,'review':'baseline-claim-review30.json','action':reviewed['action'],'reason':reviewed['reason'],'reviewedFileSha256':reviewed['fileSha256']}
        if source[row['testFile']]!=reviewed['fileSha256']:
            assert reviewed_hashes.get(row['testFile'])==source[row['testFile']], row['testFile']
            provenance['finalSourceAmendment']='Explicit final source review in supplied amendments/root review; current source hash verified.'
    else:
        assert source[row['testFile']]==row.get('source17TestSha256') or reviewed_hashes.get(row['testFile'])==source[row['testFile']], (i,row['testFile'])
        provenance={'baselineIndex':i,'review':'identical SHA256 test source to reviewed snapshot17'}
    current_claim(row,provenance)
for group,name in [(candidates['candidates'],'feature44-current-evidence-candidates30.json'),(review.get('companionCandidates',[]),'baseline-claim-review30.json companion')]:
    for r in group:
        expected=r.get('testFileSha256') or r.get('currentTestSha256')
        assert not expected or expected==source[r['testFile']] or reviewed_hashes.get(r['testFile'])==source[r['testFile']], ('Candidate source drift',r['testFile'])
        current_claim(r,{'review':name,'scope':'current source assertion candidate; execution assigned only after exact match'})
for r in amendments['evidence']+root_review.get('additionalEvidence',[]):
    current_claim(r,{'review':'Final explicit source assertions in amendments/root review'})
result={'version':2,'scope':'Reviewed baseline and feature expansion assertions; exact current execution match required, no focused totals added.',
        'baselineBundleSha256':execution['bundleSha256'],'executionManifest':a.execution,
        'sourceEvidenceInputs':['docs/security/matrix-evidence/current-evidence-17.json','baseline-claim-review30.json','feature44-current-evidence-candidates30.json',a.amendments,a.root_review],
        'evidence':claims,'unmatchedClaims':unmatched}
Path(a.output).write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({'claims':len(claims),'unmatched':unmatched},indent=2))

